{"code":"def transform(grid):
    # select the nonzero color occupying the largest number of cells;
    # break ties by its earliest raster-order occurrence
    order=[]
    freq={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                freq[v]=freq.get(v,0)+1
                if v not in order: order.append(v)
    chosen=sorted(order, key=lambda v: (-freq[v], order.index(v)))[0]
    return [[chosen]]"}

